inline bool valid_parameter(uint16_t id,float value) { const auto* p=parameter_descriptor(id); return p && value>=p->minimum && value<=p->maximum; }
inline float interpolate_parameter(uint16_t id,float a,float b,float mix) {
 if(mix<0) mix=0;
 if(mix>1) mix=1;
 const auto* p=parameter_descriptor(id); if(!p) return a;
 if(p->interpolation==Interpolation::Discrete) return mix<0.5f?a:b;
 if(p->interpolation==Interpolation::Logarithmic && a>0 && b>0) return expf(logf(a)+(logf(b)-logf(a))*mix);
 return a+(b-a)*mix;
}
inline float clamp_parameter(uint16_t id,float v){const auto* d=parameter_descriptor(id);if(!d)return 0;if(v<d->minimum)v=d->minimum;if(v>d->maximum)v=d->maximum;return ((id>=128 && id<=261) || d->interpolation==Interpolation::Discrete)?floorf(v+0.5f):v;}
