enum class LayerMode:uint8_t { Replace,Add,Multiply };
enum class MacroCurve:uint8_t { Linear,Slow,Fast,Smooth };
enum class ModSource:uint8_t { Macro,Lfo,Pressure,Envelope,Velocity };
inline const char* mod_source_name(ModSource source){static const char* names[]={"Macro","LFO","Pressure","Envelope","Velocity"};return names[unsigned(source)<=unsigned(ModSource::Velocity)?unsigned(source):0];}
constexpr unsigned kMacroRoutes=16;
inline float macro_curve(float value,MacroCurve curve){float x=value<0?0:value>1?1:value;switch(curve){case MacroCurve::Slow:return x*x;case MacroCurve::Fast:return x*(2-x);case MacroCurve::Smooth:return x*x*(3-2*x);default:return x;}}
