struct AutomationLane {bool enabled=false;uint16_t parameter=3;uint16_t length=16;LayerMode mode=LayerMode::Replace;float values[kAutomationSteps]{};};
struct MacroRoute {bool enabled=false;uint16_t parameter=3,tracks=0xffff;float low=0,high=1;LayerMode mode=LayerMode::Replace;MacroCurve curve=MacroCurve::Linear;ModSource source=ModSource::Macro;};
struct MacroState {bool active=false;float value=0;MacroRoute routes[kMacroRoutes]{};};
inline bool valid_layer(uint16_t id,LayerMode mode,float v){const auto* d=parameter_descriptor(id);if(!d || unsigned(mode)>2)return false;return mode==LayerMode::Replace?valid_parameter(id,v):mode==LayerMode::Multiply?v>=0 && v<=2:v>=-(d->maximum-d->minimum) && v<=d->maximum-d->minimum;}

