// Engine-specific slots are excluded from common Morph serialization/resolution.
inline bool morph_common_parameter(uint16_t id){return !(id>=32 && id<=36) && !(id>=80 && id<=86) && !(id>=104 && id<=107) && !(id>=600 && id<608) && !(id>=620 && id<635 && id!=632);}

constexpr unsigned kCommonMorphParameters=409;
inline uint16_t morph_parameter_at(unsigned i){return i<9?parameter_at(i):i<140?parameter_at(i+5):i<406?parameter_at(i+12):i==406?632:i<409?uint16_t(11+i-407):0;}
